from __future__ import print_function

import abc
import time

from ute_ue.exceptions import VoiceCallStopTimeoutException, VoiceCallStartTimeoutException, VoiceCallInterrupted
from ute_ue.voice_call import DefaultBaseVoiceCall

from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeManagerException


class AndroidVoiceCallAndroidApiUnder23(DefaultBaseVoiceCall):
    """Voice call operations for Android API under 23"""

    def __init__(self, name, ue_name, definition, method_proxy, logger_name='ute_ue'):
        """
        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param method_proxy:
        :param logger_name: where to put logs from this voice call
        """
        super(AndroidVoiceCallAndroidApiUnder23, self).__init__(name, ue_name, definition, logger_name)
        self.method_proxy = method_proxy

    def _merge_into_conference(self, other_call):
        raise Exception("Conference feature is not supported for Android UEs with API level below 23 (Android 6.0).")

    def _start_call_on_ue(self, to):
        if self._is_active():
            raise Exception("Previous voice call not finish")
        assert to is not None
        self._start_call_method(to)
        start_time = time.time()
        max_time = time.time() + self.definition.timeout_start_call
        while not self._is_active():
            time.sleep(1)
            if time.time() > max_time:
                t = time.time() - start_time
                msg = "Voice Call {} has taken too much time to start: {} sec, given timeout: {} sec".format(self.name,
                                                                                                             t,
                                                                                                             self.definition.timeout_start_call)
                raise VoiceCallStartTimeoutException(msg)

    def _end_call_on_ue(self, timeout=None):
        if not timeout:
            timeout = self.definition.timeout_end_call
        start_time = time.time()
        self.end_call_method()
        while self._is_active():
            time.sleep(1)
            if time.time() - start_time > timeout:
                raise VoiceCallStopTimeoutException("Voice Call %s has taken too much time to stop" % self.name)
        self.call_not_finish = False

    def _start_call_method(self, to):
        method_proxy = self.method_proxy
        method_proxy('make_call', to, self.definition.with_video)

    def end_call_method(self):
        """
        Perform finish voice call on UE PC.
        :return:
        """
        method_proxy = self.method_proxy
        method_proxy('end_call')

    def _check_voice_call_interrupted(self):
        self.logger.debug("_check_voice_call_interrupted()")
        if not self._is_active():
            self.logger.info("Voice call has been iterrupted")
            self._clean_up_after_interrupted_call()
            raise VoiceCallInterrupted()
        else:
            self.logger.debug("_check_voice_call_interrupted: voice call not interrupted")

    def _clean_up_after_interrupted_call(self):
        if self.call_not_finish:
            self._register_finished_call_time(time.time() - self.call_start_time)
            self._end_call_on_ue()
            self.call_not_finish = False

    def _is_active(self):
        self.logger.debug("_is_active called from AndroidVoiceCallAndroidApiUnder23")
        method_proxy = self.method_proxy
        return not method_proxy('get_calling_state') == 'IDL'

    def get_state(self):
        """Get call state"""
        pass

    def answer(self, with_video=False):
        """
        Answers incoming voice call.
        :type with_video:
        :return:
        """
        if with_video:
            raise UeManagerException("Android UEs with system version below 6.0 does not support video calls!")
        method_proxy = self.method_proxy
        return method_proxy('voice_call_answer_lagacy')

    def _send_dtmf(self, tones, tone_duration):
        raise NotImplementedError()

    def downgrade(self):
        """Not implemented"""
        raise NotImplementedError()

    def hold(self):
        """Not implemented"""
        raise NotImplementedError()

    def retrieve(self):
        """Not implemented"""
        raise NotImplementedError()

    def upgrade(self):
        """Not implemented"""
        raise NotImplementedError()


class AndroidVoiceCallWithUri(AndroidVoiceCallAndroidApiUnder23):
    """Managing android voice call object that has a uri"""

    __metaclass__ = abc.ABCMeta

    def __init__(self, name, ue_name, definition, method_proxy, logger_name='ute_ue'):
        """

        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param method_proxy:
        :param logger_name: where to put logs from this voice call
        """
        super(AndroidVoiceCallWithUri, self).__init__(name, ue_name, definition, method_proxy, logger_name)
        self.voice_call_uri = None
        self.is_part_of_conference = False

    def _start_call_on_ue(self, to):
        self._ensure_number_to_call_look_fine(to)
        self._look_for_my_uri()
        if self.definition.dialing_timeout <= 0:
            return
        self._await_state_active()

    def _look_for_my_uri(self):
        max_time = time.time() + self.definition.timeout_start_call
        did_i_seen_any_uri = False
        while True:
            self._perform_sleep_while_start_call_on_ue()
            if time.time() > max_time:
                self._raise_start_voice_call_timeout(did_i_seen_any_uri, max_time)
            uris = self._list_voice_calls_uris()
            did_i_seen_any_uri = did_i_seen_any_uri or uris
            _, my_uri = self._search_for_my_uri(uris)
            if my_uri:
                self.voice_call_uri = my_uri
                break

    def _raise_start_voice_call_timeout(self, did_i_seen_any_uri, max_time):
        msgp = "Voice Call %s has taken too much time to start, expected time: %.3f sec, elapsed time %.3f sec"
        elapsed_time = time.time() - max_time + self.definition.timeout_start_call
        msg = msgp % (self.name, self.definition.timeout_start_call, elapsed_time)
        if not did_i_seen_any_uri:
            msg += " and for all time no Voice Call have been seen. "
            msg += "Are you sure that mobile app (UE Manager or NAA) is set as default dialer app on the phone?"
        raise VoiceCallStartTimeoutException(msg)

    @abc.abstractmethod
    def _search_for_my_uri(self, current_uris_list):
        return False, None

    def _list_voice_calls_uris(self):
        method_proxy = self.method_proxy
        uris = method_proxy('list_voice_calls_uris')
        return uris

    def _perform_sleep_while_start_call_on_ue(self):
        time.sleep(0.5)

    def answer(self, with_video=False):
        """
        Answers incomming voice call.
        :type with_video:
        :return:
        """
        self.ensure_uri_not_null()
        method_proxy = self.method_proxy
        return method_proxy('voice_call_answer', self.voice_call_uri, with_video)

    def upgrade(self):
        """
        Upgrades to video call
        :return:
        """
        self.ensure_uri_not_null()
        method_proxy = self.method_proxy
        return method_proxy('voice_call_upgrade', self.voice_call_uri)

    def downgrade(self):
        """
        Downgrades to voice call
        :return:
        """
        self.ensure_uri_not_null()
        method_proxy = self.method_proxy
        return method_proxy('voice_call_downgrade', self.voice_call_uri)

    def disconnect(self):
        """
        Disconnects voice call.
        Use be use to reject incomming voice call.
        :return:
        """
        self.ensure_uri_not_null()
        method_proxy = self.method_proxy
        return method_proxy('voice_call_disconnect', self.voice_call_uri)

    def ensure_uri_not_null(self):
        """Raises exception if current voice call uri is None"""
        if self.voice_call_uri is None:
            raise Exception("Did not yet detect incoming voice call")

    def get_state(self, return_none_if_uri_not_found=False):
        """
        Gets current state of this voice call.
        Result is one of:
        - "STATE_ACTIVE"
        - "STATE_CONNECTING"
        - "STATE_DIALING"
        - "STATE_DISCONNECTED"
        - "STATE_DISCONNECTING"
        - "STATE_HOLDING"
        - "STATE_NEW"
        - "STATE_RINGING"
        - "STATE_SELECT_PHONE_ACCOUNT"
        :return: string
        """
        self.ensure_uri_not_null()
        method_proxy = self.method_proxy
        try:
            return method_proxy('get_voice_call_state', self.voice_call_uri)
        except Exception as e:
            if return_none_if_uri_not_found and "Not found call with uri:" in str(e):
                return None
            raise

    def _merge_into_conference(self, other_call):
        """
        Make a conference with other call.
        Makes several checks if it is possible to start conference call.
        To make a conference both voice call have to be on same UE.
        :param other_call: AndroidVoiceCallWithUri
        """
        if not isinstance(other_call, AndroidVoiceCallWithUri):
            msg = "can not make conference. second call need to be instance of class AndroidVoiceCallWithUri, givien type: {}".format(
                type(other_call))
            raise UeManagerException(msg)
        self.ensure_uri_not_null()
        other_call.ensure_uri_not_null()
        if self.voice_call_uri == other_call.voice_call_uri:
            raise UeManagerException("Can not merge same call")
        method_proxy = self.method_proxy
        result = method_proxy('voice_call_conference', self.voice_call_uri, other_call.voice_call_uri)
        if result != 'success':
            raise UeManagerException("Conference call did not started, conference call result: {}".format(result))
        print("conference call result: {}".format(result))
        self.is_part_of_conference = True
        other_call.is_part_of_conference = True

    def start_recording(self):
        """Start voice call recording."""
        method_proxy = self.method_proxy
        result = method_proxy('voice_call_start_recording', self.voice_call_uri)
        if result != 'success':
            raise UeManagerException("Could not start recording: {}".format(result))
        print("Starting voice call recording: {}".format(result))

    def stop_recording(self, local_file_dir):
        """
        Stop voice call recording.
        :param local_file_dir: str
        """
        method_proxy = self.method_proxy
        result = method_proxy('voice_call_stop_recording', self.voice_call_uri, local_file_dir)
        if result != 'success':
            raise UeManagerException("Could not stop recording: {}".format(result))
        print("Stopping voice call recording: {}".format(result))

    def _send_dtmf(self, tones, tone_duration):
        """
        Sends DTMF tones through voice channel.
        :param tones:
        :param tone_duration:
        :return:
        """
        method_proxy = self.method_proxy
        try:
            for tone in tones:
                result = method_proxy('voice_call_send_dtmf', self.voice_call_uri, tone)
                if result != 'success':
                    raise UeManagerException("Could not send DTMF: {}".format(result))
                print("Sent DTMF tone: {}".format(result))

                time.sleep(tone_duration)

        finally:
            result = method_proxy('voice_call_stop_dtmf', self.voice_call_uri)
            if result != 'success':
                raise UeManagerException("Could not stop DTMF transmission: {}".format(result))
            print("Stopped DTMF tone: {}".format(result))

    def _get_my_ue_imei(self):
        method_proxy = self.method_proxy
        return method_proxy('get_ue_info', 'IMEI')

    def _get_conferencable_calls(self):
        method_proxy = self.method_proxy
        return method_proxy('voice_call_get_conferencable_calls', self.voice_call_uri)

    def _end_call_on_ue(self):
        self.disconnect()
        # TODO: oczekiwanie z timeout az moj uri zniknie

    # @abc.abstractmethod
    # def _is_this_uri_looks_like_mine(self, uri):
    #     pass

    @abc.abstractmethod
    def _ensure_number_to_call_look_fine(self, to):
        pass

    def _await_state_active(self):
        if self.definition.dialing_timeout < 0:
            return
        time_start = time.time()
        end_time = time.time() + self.definition.dialing_timeout
        while time.time() < end_time:
            state = self.get_state(return_none_if_uri_not_found=True)
            if state is None:
                raise VoiceCallDisappearedException(
                    "while awating for active state of voice call, voice call has disappeared")
            print("i am awaiting for active, my state is {}".format(state))
            if state in ['STATE_ACTIVE', 'STATE_HOLDING', 'STATE_RINGING']:  # FIX ME pls
                return

            time.sleep(1)
        msgp = "Voice Call after {} seconds from start is still in state dialing. Current timeout is {} seconds."
        raise VoiceCallIsStillDialing(msgp.format(time.time() - time_start, self.definition.dialing_timeout))

    def hold(self):
        """Holds started Voice Call"""
        # TODO: ensure if raise exception if Voice Call is not ACTIVE
        method_proxy = self.method_proxy
        method_proxy('voice_call_hold', self.voice_call_uri)

    def unhold(self):
        """Unhold holded Voive Call."""
        # TODO: ensure if raise exception if Voice Call is not HOLDED
        method_proxy = self.method_proxy
        method_proxy('voice_call_unhold', self.voice_call_uri)

    def retrieve(self):
        """
        Just call unhold()
        :return:
        """
        self.unhold()

    def _is_iterrupted(self):
        state = self.get_state(return_none_if_uri_not_found=True)
        if state is None:
            self.logger.debug(
                "_is_iterrupted called from AndroidVoiceCallWithUri, result = True, because state is None")
            return True
        active_ = state == 'STATE_HOLDING' or state == 'STATE_ACTIVE'
        result = not active_
        self.logger.debug("_is_iterrupted called from AndroidVoiceCallWithUri, result = {}".format(result))
        return result

    def _check_voice_call_interrupted(self):
        if self.voice_call_uri not in self._list_voice_calls_uris():
            if not self.is_part_of_conference:
                self.call_not_finish = False
                raise VoiceCallInterrupted("Voice call uri disappeared")
            self._conference_failsafe()
            return
        state = self.get_state()
        if not self._is_call_state_active(state):
            self._clean_up_after_interrupted_call()
            raise VoiceCallInterrupted("Voice call interrupted, state: {}".format(state))

    @staticmethod
    def _is_call_state_active(state):
        return state in ['STATE_CONNECTING', 'STATE_DIALING', 'STATE_HOLDING', 'STATE_ACTIVE']

    def _conference_failsafe(self):
        """
        Conference fail safe.
        Some ues behave poorly with conference calls.
        Once such call is being started all references to individual calls its composed of are being dropped.
        In such case we are only able to kill conference itself.
        :return:
        """
        method_proxy = self.method_proxy
        try:
            method_proxy('kill_all_voice_calls')
        except UeManagerException as e:
            raise UeManagerException("Could not handle conference with fail safe! Reason: {}".format(str(e)))
        self._register_finished_call_time(time.time() - self.call_start_time)
        self.call_not_finish = False


class AndroidIncomingVoiceCall(AndroidVoiceCallWithUri):
    """Managing incoming voice call objects"""

    def __init__(self, *args, **kwargs):
        """

        :param args:
        :param kwargs:
        """
        super(AndroidIncomingVoiceCall, self).__init__(*args, **kwargs)
        # TODO: old logger was "AndroidIncomingVoiceCall", do we need "incomming" info?
        self._start_call_on_ue(self.definition.to)

    def _start_call_on_ue(self, to):
        method_proxy = self.method_proxy
        if method_proxy('is_auto_call_answering'):
            raise NotSupportedTrackingVoiceCallOnAutoresponder(
                "Not support tracking incomming voice call when auto_call_answering is ON. Please turn it OFF")
        super(AndroidIncomingVoiceCall, self)._start_call_on_ue(to)

    def _ensure_number_to_call_look_fine(self, to):
        assert to is None

    def _search_for_my_uri(self, current_uris_list):
        ringing_uris = [uri for uri in current_uris_list if self._is_ringing(uri)]
        if not ringing_uris:
            return False, None
        elif len(ringing_uris) == 1:
            uri = ringing_uris[0]
            self._ensure_uri_has_state_like_incomming_call(uri)
            return True, uri
        return self._raise_too_many_uris_appeared(current_uris_list, ringing_uris)

    def _is_ringing(self, uri):
        method_proxy = self.method_proxy
        have = method_proxy('if_voice_call_state_ringing', uri)
        return have

    def _raise_too_many_uris_appeared(self, current_uris_list, ringing_uris):
        msgp = "Too many uris appear when starting incomming voice call, ringing_uris: {}, current_uris_list: {}"
        msg = msgp.format(', '.join(ringing_uris), ', '.join(current_uris_list))
        raise UeManagerException(msg)

    def _ensure_uri_has_state_like_incomming_call(self, uri):
        if self._is_ringing(uri):
            return
        method_proxy = self.method_proxy
        state = method_proxy('get_voice_call_state', uri)
        raise UeManagerException("unexpected state of just started voice call: {}".format(state))


class AndroidOutgoingVoiceCall(AndroidVoiceCallWithUri):
    """Managing outgoing voice call object"""

    def __init__(self, *args, **kwargs):
        """

        :param args:
        :param kwargs:
        """
        super(AndroidOutgoingVoiceCall, self).__init__(*args, **kwargs)
        # TODO: old logger was "AndroidOutgoingVoiceCall", do we need "outgoing" info?
        self._uris_before_start_voice_call = None

    def _ensure_number_to_call_look_fine(self, to):
        assert to is not None  # and isinstance(to, basestr)

    def _start_call_on_ue(self, to):
        self._uris_before_start_voice_call = self._list_voice_calls_uris()
        self._start_call_method(to)
        super(AndroidOutgoingVoiceCall, self)._start_call_on_ue(to)

    def _search_for_my_uri(self, current_uris_list):
        new_uris = [uri for uri in current_uris_list if uri not in self._uris_before_start_voice_call]
        if not new_uris:
            return False, None
        elif len(new_uris) == 1:
            uri = new_uris[0]
            try:
                self._ensure_uri_has_state_like_outcomming_call(uri)
                return True, uri
            except UeManagerException as e:
                print("[Android] Got exception in _ensure_uri_has_state_like_outcomming_call: {}".format(e))
                return False, None
        return self._raise_too_many_uris_appeared(current_uris_list, new_uris)

    def _raise_too_many_uris_appeared(self, current_uris_list, new_uris):
        msgp = "Too many uris appear when starting outcomming voice call, new_uris: {}, current_uris_list: {}, _uris_before_start_voice_call: {}"
        msg = msgp.format(', '.join(new_uris), ', '.join(current_uris_list),
                          ', '.join(self._uris_before_start_voice_call))
        raise UeManagerException(msg)

    def _ensure_uri_has_state_like_outcomming_call(self, uri):
        method_proxy = self.method_proxy
        state = method_proxy('get_voice_call_state', uri)
        if state == 'STATE_DIALING' or state == 'STATE_ACTIVE' or state == 'STATE_HOLDING' or state == 'STATE_CONNECTING':
            return
        raise UeManagerException("unexpected state of just started voice call: {}".format(state))


class AndroidEmergencyVoiceCall(DefaultBaseVoiceCall):
    """Managing emergency call done with emergency dialer"""
    def __init__(self, name, ue_name, definition, method_proxy, logger_name='ute_ue'):
        """
        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param method_proxy:
        :param logger_name: where to put logs from this voice call
        """
        super(AndroidEmergencyVoiceCall, self).__init__(name, ue_name, definition, logger_name)
        self.method_proxy = method_proxy

    def _start_call_on_ue(self, to):
        method_proxy = self.method_proxy
        method_proxy("make_emergency_call", to)

    def _end_call_on_ue(self, timeout=5):
        method_proxy = self.method_proxy
        method_proxy("end_emergency_call")

        # There is possible call with uri on hold
        # Therefore we cannot confirm which on is active at the moment with isInCall
        if not self._list_voice_calls_uris():
            # TODO find other method to detect emergency call active state
            self._await_call_end(timeout=timeout)

    def _await_call_end(self, timeout):
        end_time = time.time() + timeout
        while not self._is_iterrupted():
            self.logger.debug("Awaiting emergency call end.")
            if time.time() > end_time:
                raise Exception("Unable to end emergency call.")
            time.sleep(0.5)

    def _is_iterrupted(self):  # iNterrupted typo at ute_ue level, to be corrected... :)
        """
        Currently uses :
        https://developer.android.com/reference/android/telecom/TelecomManager#isInCall()
        So this detects any state of outgoing call: dialing, ringing, active or holding
        We may need to update implementation and use phone state listener
        # https://developer.android.com/reference/android/telephony/PhoneStateListener
        """
        method_proxy = self.method_proxy
        is_in_call = method_proxy("is_in_call")
        self.logger.debug("Call ongoing: {}".format(is_in_call))
        return not is_in_call

    def _list_voice_calls_uris(self):
        method_proxy = self.method_proxy
        uris = method_proxy('list_voice_calls_uris')
        return uris

    def _send_dtmf(self, tones, tone_duration):
        raise IllegalVoiceCallAction("_send_dtmf")

    def downgrade(self):
        raise IllegalVoiceCallAction("downgrade")

    def upgrade(self):
        raise IllegalVoiceCallAction("upgrade")

    def answer(self, with_video=False):
        raise IllegalVoiceCallAction("answer")

    def retrieve(self):
        raise IllegalVoiceCallAction("retrieve")

    def hold(self):
        raise IllegalVoiceCallAction("hold")

    def _merge_into_conference(self, other_call):
        raise IllegalVoiceCallAction("_merge_into_conference")


class VoiceCallIsStillDialing(UeManagerException):
    """Exception"""
    pass


class VoiceCallNotAppeared(UeManagerException):
    """Exception"""
    pass


class NotSupportedMoreThanOneRingingVoiceCall(UeManagerException):
    """Exception"""
    pass


class NotSupportedTrackingVoiceCallOnAutoresponder(UeManagerException):
    """Exception"""
    pass


class VoiceCallDisappearedException(UeManagerException):
    """Exception"""
    pass


class IllegalVoiceCallAction(UeManagerException):
    """Raised when action on voice call is not allowed"""
    pass
